import { View, Text, Pressable, Alert, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

function App() {
  return (
    <View style={styles.screen}>
      <Text style={styles.name}>Утасгүй чихэвч</Text>
      {/* энд бичнэ үү: Сагслах товч, дархад мэдэгдэл */}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 16, justifyContent: "center" },
  name: { fontSize: 20, fontWeight: "600", textAlign: "center" },
  btn: { backgroundColor: "#2563eb", padding: 16, borderRadius: 12, alignItems: "center" },
  btnText: { color: "#ffffff", fontSize: 16, fontWeight: "bold" },
